local COLS, ROWS = 15, 13     -- map size in tiles (240 x 208)
local MX, MY = 0, 5           -- map position on screen
local HX = 246                -- HUD column
local FUSE = 2.4              -- seconds before a bomb goes off
local FLAME_T = 0.5           -- seconds a flame burns
local BREAK_T = 0.45          -- seconds a block takes to break
local STAGE_TIME = 200        -- seconds per stage
local BG = 0x0B0A14

local floor, abs, min, max = math.floor, math.abs, math.min, math.max
local random = math.random

