-- ------------------------------------------------------------------ images
local IMG = {}
local loaded_world = 0

local function palette_for(w)
  local p = {}
  for k, v in pairs(A.pal) do p[k] = v end
  local W = A.worlds[w]
  p.F, p.E, p.B, p.L, p.D = W.F, W.E, W.B, W.L, W.D
  return p
end

-- Sprites that use world colours (F E B L D) are reloaded on a world change.
local WORLD_SPRITES = {}
for name, rows in pairs(A.s) do
  for _, r in ipairs(rows) do
    if r:find("[FEBLD]") then WORLD_SPRITES[name] = true break end
  end
end

local function load_world(w)
  if loaded_world == w then return end
  local pal = palette_for(w)
  for name, rows in pairs(A.s) do
    if loaded_world == 0 or WORLD_SPRITES[name] then
      IMG[name] = ui.load(rows, {palette = pal})
    end
  end
  if loaded_world == 0 then
    -- GOLD VAL (all five secrets): the hero sprites in gold
    local gold = palette_for(w)
    gold.p, gold.P, gold.v, gold.a = 0xFFD84A, 0xC98A1E, 0xFFF3B0, 0xFFF3B0
    for _, f in ipairs({"d0", "d1", "d2", "u0", "u1", "u2", "l0", "l1", "l2", "r0", "r1", "r2",
        "x1", "x2", "x3", "x4"}) do
      IMG["gold_" .. f] = ui.load(A.s["hero_" .. f], {palette = gold})
    end
  end
  loaded_world = w
end

