-- ------------------------------------------------------------------ save
local function int_or(v, lo, hi, def)
  if type(v) ~= "number" or v ~= v or v < lo or v > hi then return def end
  return floor(v)
end

local save = {
  best = int_or(storage.get("best"), 0, 2000000000, 0),
  stage = int_or(storage.get("stage"), 1, 8, 1),
  epoch = int_or(storage.get("epoch"), 1, 999, 1),
}

local function persist()
  storage.set("best", save.best)
  storage.set("stage", save.stage)
  storage.set("epoch", save.epoch)
end

-- ------------------------------------------------------------------ !LAMP rewards
-- Once per day each: 1 for the first clear of each stage (max 8), 5 for finishing an
-- epoch (stage 4-2), 2 for a new best score. At most 15 a day; replays earn nothing.
-- The server's award cap is the real limit; this only keeps the app from asking twice.
local LAMP_STAGE, LAMP_EPOCH, LAMP_BEST = 1, 5, 2
local needs_x = false            -- the server said "link X first": stop asking this session
local lamp_pending = {}          -- awards asked for and not answered yet (this session only)
local lamp_session = {}          -- what this session already got, for badges without a clock

local function today()
  local t = sys.time and sys.time()
  if not t then return nil end
  return floor(t / 86400)
end

local function lamp_log()
  local d = today()
  if not d then return nil end
  local log = storage.get("lamps")
  if type(log) ~= "table" or log.day ~= d then log = {day = d, got = {}} end
  if type(log.got) ~= "table" then log.got = {} end
  return log
end

-- key: "s3" (stage 3), "epoch" or "best".
local function award(key, amount, reason)
  if not lamps or not lamps.award or needs_x then return end
  local log = lamp_log()       -- nil when the badge has no clock yet: the session guards it
  local day = log and log.day
  local skey = key .. "@" .. tostring(day)
  if (log and log.got[key]) or lamp_session[skey] or lamp_pending[key] then return end
  lamp_pending[key] = true
  lamps.award(amount, reason, function(ok, r)
    lamp_pending[key] = nil
    if ok and type(r) == "table" and r.needsX then
      -- not linked yet: say so once and stop asking until the next launch
      needs_x = true
      ui.toast("Link X in My Badge to earn !LAMPs")
      return
    end
    if not ok then return end      -- offline or busy: ask again next time
    lamp_session[skey] = true      -- paid, or the daily cap is used up: not again this session
    local got = type(r) == "table" and (tonumber(r.awarded) or 0) or 0
    if got <= 0 then return end    -- capped: a later launch today may still be paid
    ui.toast("+" .. got .. " !LAMP" .. (got > 1 and "s" or "") .. "  " .. reason)
    local now = lamp_log()
    if now and now.day == day then -- an answer after midnight does not use up the new day
      now.got[key] = true
      storage.set("lamps", now)
    end
  end)
end

-- ------------------------------------------------------------------ secrets
-- Five secrets, listed with hints under SECRETS on the title. Each one found pays
-- 1 !LAMP once ever; all five pay 3 more and unlock the GOLD VAL skin.
local SECRETS = {
  {id = "ibrl", name = "IBRL MODE", hint = "Start menu: up up down down, then...",
    how = "UP UP DOWN DOWN LEFT RIGHT LEFT RIGHT"},
  {id = "skin", name = "TRIBUTE SKINS", hint = "Start menu: left right left right, then...",
    how = "LEFT RIGHT LEFT RIGHT UP UP"},
  {id = "gm", name = "GM", hint = "Start menu: up down up down, then...",
    how = "UP DOWN UP DOWN LEFT RIGHT"},
  {id = "poh", name = "PROOF OF HISTORY", hint = "In a stage: clear it in under 60 seconds.",
    how = "clear a stage in under 60 s: +1500"},
  {id = "wagmi", name = "WAGMI", hint = "In a stage: blocks draw a picture. Erase it.",
    how = "break every block of the picture: +2000"},
}
local LAMP_SECRET, LAMP_ALL_SECRETS = 1, 3
local found = {}
local paid = {}
do
  local s = storage.get("secrets")
  if type(s) == "table" then
    for _, it in ipairs(SECRETS) do if s[it.id] == true then found[it.id] = true end end
  end
  local p = storage.get("spaid")
  if type(p) == "table" then
    for k, v in pairs(p) do if v == true and type(k) == "string" then paid[k] = true end end
  end
end
local secret_tried = {}            -- asked this session already (a capped day retries next launch)

local function secrets_count()
  local n = 0
  for _, it in ipairs(SECRETS) do if found[it.id] then n = n + 1 end end
  return n
end

local function all_secrets() return secrets_count() == #SECRETS end

-- !LAMPs for a secret, once ever: kept unpaid until the server actually pays
local function pay_secret(key, amount, reason)
  if paid[key] or secret_tried[key] or not lamps or not lamps.award or needs_x then return end
  secret_tried[key] = true
  lamps.award(amount, reason, function(ok, r)
    if ok and type(r) == "table" and r.needsX then
      needs_x = true
      ui.toast("Link X in My Badge to earn !LAMPs")
      return
    end
    if not ok then secret_tried[key] = nil return end   -- offline: ask again later
    if type(r) == "table" and (r.awarded or 0) > 0 then
      paid[key] = true
      storage.set("spaid", paid)
      ui.toast("+" .. r.awarded .. " !LAMP" .. (tonumber(r.awarded) > 1 and "s" or "") .. "  " .. reason)
    end
  end)
end

-- secrets found earlier whose !LAMPs did not come through yet
local function pay_secrets_due()
  for _, it in ipairs(SECRETS) do
    if found[it.id] then pay_secret(it.id, LAMP_SECRET, "secret: " .. it.name) end
  end
  if all_secrets() then pay_secret("all", LAMP_ALL_SECRETS, "all secrets found") end
end

-- Marks a secret found. Returns a prefix for the caller's toast ("" if it was known).
local function find_secret(id)
  if found[id] then return "" end
  found[id] = true
  storage.set("secrets", found)
  local name = id
  for _, it in ipairs(SECRETS) do if it.id == id then name = it.name end end
  pay_secret(id, LAMP_SECRET, "secret: " .. name)
  local n = secrets_count()
  if n == #SECRETS then
    pay_secret("all", LAMP_ALL_SECRETS, "all secrets found")
    settings.skin = "gold"           -- wear the prize right away (the skin code cycles it)
    save_settings()
    flash(0xFFD84A, 1.0)
    return "ALL 5 SECRETS! GOLD VAL unlocked. "
  end
  flash(0xFF6FB5, 0.4)
  return "SECRET " .. n .. "/" .. #SECRETS .. "! "
end

-- ------------------------------------------------------------------ leaderboard
-- Scores go to our own server; the badge server signs each request, so the
-- server knows which badge owner sent it (server/worker.js).
local LB = "https://forkbomb-scores.hypnogaba.workers.dev"
local LB_ERR = {
  offline = "Offline: join Wi-Fi to see the board",
  ["not linked"] = "Claim this badge in My Badge first",
  denied = "The board opens once FORK BOMB is in the store",
  busy = "Badge busy, try again", timeout = "No answer, try again",
  ["too fast"] = "Too fast, wait a moment", unreachable = "Server unreachable",
}

local function lb_name()
  if not settings.name then return "anon" end
  return badge and badge.owner and badge.owner() or "anon"
end

local function submit_score(score, stage, epoch, cb)
  if not http or score <= 0 then return end
  http.post(LB .. "/score", {score = score, stage = stage, epoch = epoch, name = lb_name()}, function(ok, res)
    if ok and res.status == 200 then
      if cb then cb(true, res) end
      return
    end
    -- no answer, or the server is struggling: keep the best unsent score for later.
    -- A 4xx is final (the server refused this score), so it is not retried.
    local retry = not ok or res.status >= 500 or res.status == 429
    local p = storage.get("lb_pending")
    if retry and (type(p) ~= "table" or (tonumber(p.score) or 0) < score) then
      storage.set("lb_pending", {score = score, stage = stage, epoch = epoch})
    end
    if cb then cb(false, ok and ("server said " .. res.status) or res) end
  end)
end

local function flush_pending()
  local p = storage.get("lb_pending")
  if http and type(p) == "table" and type(p.score) == "number" then
    storage.remove("lb_pending")      -- stored again if this try fails too
    submit_score(int_or(p.score, 1, 5000000, 0), int_or(p.stage, 1, 8, 1), int_or(p.epoch, 1, 999, 1))
  end
end

