local function idx(c, r) return r * COLS + c end

-- "1-2", or "2:1-2" from the second epoch on
local function stage_name(stage, epoch)
  local st = STAGES[stage]
  return (epoch > 1 and (epoch .. ":") or "") .. st.w .. "-" .. ((stage - 1) % 2 + 1)
end

