-- ------------------------------------------------------------------ map building
local function build_map(st)
  local g = {}
  local deco = {}
  for r = 0, ROWS - 1 do
    for c = 0, COLS - 1 do
      local t = FLOOR
      if r == 0 or c == 0 or r == ROWS - 1 or c == COLS - 1 then
        t = WALL
      elseif st.layout == "open" then
        if r % 2 == 0 and c % 4 == 2 then t = WALL end
        if r % 4 == 0 and c % 2 == 0 then t = WALL end
      elseif c % 2 == 0 and r % 2 == 0 then
        t = WALL
      end
      g[idx(c, r)] = t
    end
  end
  -- the picture: fork blocks in the shape of a logo or a word, in an open middle
  local logo = {}
  local function clear_box(c0, r0, c1, r1)
    for r = r0, r1 do
      for c = c0, c1 do
        if g[idx(c, r)] == WALL then g[idx(c, r)] = FLOOR end
        logo[idx(c, r)] = false        -- inside the picture: no random blocks
      end
    end
  end
  local function put(c, r, name)
    g[idx(c, r)] = BLOCK
    deco[idx(c, r)] = name
    logo[idx(c, r)] = true
  end
  local pat = st.pattern
  if pat == "solana" then
    clear_box(2, 2, 12, 10)
    for n, r in ipairs({3, 6, 9}) do
      for c = 3, 11 do
        put(c, r, "bar" .. n .. ((c == 3) and "l" or (c == 11) and "r" or "c"))
      end
    end
  elseif pat == "dz" then
    clear_box(1, 2, 13, 10)
    for k, c0 in ipairs({2, 8}) do
      for y, row in ipairs(ZERO) do
        for x = 1, #row do
          if row:sub(x, x) == "#" then put(c0 + x - 1, 2 + y, k == 1 and "lb_w" or "lb_p") end
        end
      end
    end
  elseif pat then
    local wdt = #pat * 4 - 1
    local c0 = 1 + (13 - wdt) // 2
    clear_box(c0 - 1, 3, c0 + wdt, 9)
    for k = 1, #pat do
      local glyph = FONT[pat:sub(k, k)]
      for y, row in ipairs(glyph) do
        for x = 1, 3 do
          if row:sub(x, x) == "#" then
            put(c0 + (k - 1) * 4 + x - 1, 3 + y, "lb_" .. LETTER_COLS[(k - 1) % 3 + 1])
          end
        end
      end
    end
  end
  -- fork blocks around the picture
  local blocks = {}
  for r = 1, ROWS - 2 do
    for c = 1, COLS - 2 do
      local i = idx(c, r)
      local safe = (c + r) <= 3
      if logo[i] then
        blocks[#blocks + 1] = i
      elseif g[i] == FLOOR and not safe and logo[i] == nil and random() < st.density then
        g[i] = BLOCK
        blocks[#blocks + 1] = i
      end
    end
  end
  -- the gate and the power-up need two blocks: force them if the dice said no
  local r = ROWS - 2
  for c = COLS - 2, 1, -1 do
    if #blocks >= 2 then break end
    local i = idx(c, r)
    if g[i] == FLOOR then g[i] = BLOCK blocks[#blocks + 1] = i end
  end
  return g, deco, blocks, logo
end

local function passable_tile(c, r, ghost)
  if c < 0 or r < 0 or c >= COLS or r >= ROWS then return false end
  local t = G.grid[idx(c, r)]
  if t == FLOOR then return true end
  if t == BLOCK and ghost and c > 0 and r > 0 and c < COLS - 1 and r < ROWS - 1 then return true end
  return false
end

-- ------------------------------------------------------------------ drawing the map
local function tile_sig(i)
  local t = G.grid[i]
  local base
  if t == WALL then base = "wall"
  elseif t == BAR then base = G.deco[i]
  elseif t == BLOCK then
    local b = G.breaking[i]
    if b then
      local k = BREAK_T - b
      base = k < 0.15 and "break1" or k < 0.3 and "break2" or "break3"
    else
      base = G.deco[i] or "block"
    end
  else base = "floor" end
  local over = ""
  local f = G.flames[i]
  if f then
    local age = FLAME_T - f.t
    local s = age < 0.07 and 2 or age < 0.33 and 3 or age < 0.42 and 2 or 1
    over = "fire_" .. f.kind .. s
  elseif G.bombs[i] then
    local b = G.bombs[i]
    local ph = b.remote and not b.lit and floor(G.clock * 4) % 3
      or floor((FUSE - b.t) * (b.t < 0.8 and 10 or 5)) % 3
    over = "bomb" .. (ph + 1)
  elseif t ~= BLOCK then
    local it = G.items[i]
    if it then
      local blink = floor(G.clock * 4) % 2 + 1
      if it == "gate" then
        if G.open then over = "gate" .. (floor(G.clock * 8) % 3 + 1) else over = "gate0" end
      else
        over = "pu_" .. it .. blink
      end
    end
  end
  if t == BLOCK and G.breaking[i] then
    -- falling pieces over the floor
    return "floor", base
  end
  return base, over
end

local function draw_tile(i)
  local base, over = tile_sig(i)
  local d = G.drawn[i]
  if d and d[1] == base and d[2] == over then return end
  if d then d[1], d[2] = base, over else G.drawn[i] = {base, over} end
  local x, y = (i % COLS) * T, (i // COLS) * T
  if base ~= "floor" and base ~= "wall" and base ~= "block" then
    canvas:image(IMG.floor, x, y)   -- bars have see-through corners
  end
  canvas:image(IMG[base], x, y)
  if over ~= "" then canvas:image(IMG[over], x, y) end
end

local function touch(i) G.touched[i] = true end

local function redraw_dirty()
  for i in pairs(G.touched) do draw_tile(i) end
  G.touched = {}
  for i in pairs(G.bombs) do draw_tile(i) end
  for i in pairs(G.flames) do draw_tile(i) end
  for i in pairs(G.breaking) do draw_tile(i) end
  for i in pairs(G.items) do
    if G.grid[i] ~= BLOCK then draw_tile(i) end
  end
end

-- ------------------------------------------------------------------ HUD
local function hud_build(st)
  local W = A.worlds[st.w]
  hud.stage_t = ui.label(HX, 2, "STAGE", {size = 12, color = "dim"})
  hud.stage = ui.label(HX, 14, "", {size = 20, color = "text"})
  hud.world = ui.label(HX, 38, W.name, {size = 12, color = W.L})
  hud.score_t = ui.label(HX, 56, "SCORE", {size = 12, color = "dim"})
  hud.score = ui.label(HX, 68, "0", {size = 14, color = "text"})
  local rows = {
    {"i_clock", "time"}, {"i_life", "lives"}, {"i_bomb", "bombs"},
    {"i_fire", "fire"}, {"i_speed", "speed"},
  }
  for n, row in ipairs(rows) do
    local y = 90 + (n - 1) * 20
    hud["ic_" .. row[2]] = ui.image(HX, y, IMG[row[1]], {scale = 2})
    hud[row[2]] = ui.label(HX + 22, y + 1, "", {size = 14, color = "text"})
  end
  -- a row of what the player has on: outage, shield, kick, remote, firedancer, zk pass
  hud.slots = {}
  for n = 1, 4 do
    local im = ui.image(HX + (n - 1) * 18, 192, IMG.i_shield, {scale = 2})
    im:show(false)
    hud.slots[n] = im
  end
end

local last_hud = {}
local function hud_set(key, text, color)
  if last_hud[key] == text then return end
  last_hud[key] = text
  hud[key]:text(text)
  if color then hud[key]:color(color) end
end

local function hud_update()
  hud_set("stage", stage_name(run.stage, run.epoch))
  hud_set("score", tostring(run.score))
  local t = max(0, floor(G.time))
  hud_set("time", tostring(t), t <= 30 and "orange" or "text")
  hud_set("lives", "x" .. run.lives)
  hud_set("bombs", "x" .. run.bombs)
  hud_set("fire", "x" .. run.fire)
  hud_set("speed", "x" .. run.speed)
  local p = G.player
  local on = hud.on or {}
  hud.on = on
  for n = 1, 6 do on[n] = nil end
  if p.curse then on[#on + 1] = "i_curse" end
  if p.shield > 0 and (p.shield > 3 or floor(p.shield * 4) % 2 == 0) then on[#on + 1] = "i_shield" end
  if run.kick then on[#on + 1] = "i_kick" end
  if run.remote then on[#on + 1] = "i_remote" end
  if run.pierce then on[#on + 1] = "i_pierce" end
  if run.pass then on[#on + 1] = "i_pass" end
  for n = 1, 4 do
    local name = on[n] or ""
    if last_hud["slot" .. n] ~= name then
      last_hud["slot" .. n] = name
      if on[n] then hud.slots[n]:set(IMG[name]) end
      hud.slots[n]:show(on[n] ~= nil)
    end
  end
end

-- ------------------------------------------------------------------ score popups
local function popup(x, y, text)
  if #popups >= 4 then
    popups[1].l:remove()
    table.remove(popups, 1)
  end
  local l = ui.label(MX + x - 8, MY + y, text, {size = 12, color = "yellow"})
  popups[#popups + 1] = {l = l, t = 0.8, x = MX + x - 8, y = MY + y}
end

local function update_popups(dt)
  for k = #popups, 1, -1 do
    local p = popups[k]
    p.t = p.t - dt
    p.y = p.y - dt * 20
    if p.t <= 0 then
      p.l:remove()
      table.remove(popups, k)
    else
      p.l:pos(floor(p.x), floor(p.y))
    end
  end
end

local function clear_popups()
  for _, p in ipairs(popups) do p.l:remove() end
  popups = {}
end

-- ------------------------------------------------------------------ entities
local DIRS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}}

local function ent_tile(e)
  return floor((e.x + 8) / T), floor((e.y + 8) / T)
end

local function make_foe(kind, c, r)
  local def = FOES[kind]
  local e = {
    kind = kind, x = c * T, y = r * T, tc = c, tr = r, dx = 0, dy = 0,
    speed = def.speed * (1 + 0.15 * (run.epoch - 1)) * (ibrl and 1.3 or 1),
    ghost = def.ghost, alive = true, dying = 0, anim = random() * 2,
  }
  e.img = ui.image(MX + e.x, MY + e.y, IMG[kind .. "1"])
  G.foes[#G.foes + 1] = e
  return e
end

local function foe_can(e, c, r)
  if not passable_tile(c, r, e.ghost) then return false end
  if G.bombs[idx(c, r)] then return false end
  return true
end

local function sees_player(e, range)
  local pc, pr = ent_tile(G.player)
  if pc ~= e.tc and pr ~= e.tr then return nil end
  local dx = pc > e.tc and 1 or pc < e.tc and -1 or 0
  local dy = pr > e.tr and 1 or pr < e.tr and -1 or 0
  local c, r = e.tc, e.tr
  for _ = 1, range do
    if c == pc and r == pr then return dx, dy end
    c, r = c + dx, r + dy
    if not foe_can(e, c, r) then return nil end
  end
  if c == pc and r == pr then return dx, dy end
  return nil
end

local function choose_dir(e)
  local opts = {}
  for _, d in ipairs(DIRS) do
    if foe_can(e, e.tc + d[1], e.tr + d[2]) then opts[#opts + 1] = d end
  end
  if #opts == 0 then e.dx, e.dy = 0, 0 return end
  local function keep()
    return (e.dx ~= 0 or e.dy ~= 0) and foe_can(e, e.tc + e.dx, e.tr + e.dy)
  end
  local function pick()
    -- avoid turning straight back when there is another way
    if #opts > 1 then
      local o2 = {}
      for _, d in ipairs(opts) do
        if not (d[1] == -e.dx and d[2] == -e.dy) then o2[#o2 + 1] = d end
      end
      if #o2 > 0 then opts = o2 end
    end
    local d = opts[random(#opts)]
    e.dx, e.dy = d[1], d[2]
  end
  if e.kind == "rug" then
    if keep() and random() > 0.15 then return end
    pick()
  elseif e.kind == "jeet" then
    if keep() and random() > 0.5 then return end
    pick()
  elseif e.kind == "sand" then
    local dx, dy = sees_player(e, 6)
    if dx and foe_can(e, e.tc + dx, e.tr + dy) then e.dx, e.dy = dx, dy e.chasing = true return end
    e.chasing = false
    if keep() and random() > 0.25 then return end
    pick()
  elseif e.kind == "fud" then
    local pc, pr = ent_tile(G.player)
    if random() < 0.55 then
      local best, bd = nil, 999
      for _, d in ipairs(opts) do
        local dd = abs(e.tc + d[1] - pc) + abs(e.tr + d[2] - pr)
        if dd < bd then best, bd = d, dd end
      end
      e.dx, e.dy = best[1], best[2]
      return
    end
    if keep() and random() > 0.3 then return end
    pick()
  end
end

local function update_foe(e, dt)
  e.anim = e.anim + dt
  if not e.alive then
    e.dying = e.dying + dt
    if e.dying < 0.3 then
      e.img:set(IMG[e.kind .. "_x1"])
    elseif e.dying < 0.6 then
      e.img:set(IMG[e.kind .. "_x2"])
    elseif e.dying < 0.85 then
      e.img:set(IMG.puff)
    else
      e.img:remove()
      e.gone = true
    end
    return
  end
  local spd = e.speed * (e.chasing and 1.3 or 1)
  local dist = spd * dt
  local guard = 0
  while dist > 0 and guard < 4 do
    guard = guard + 1
    local tx, ty = e.tc * T, e.tr * T
    if e.x == tx and e.y == ty then
      choose_dir(e)
      if e.dx == 0 and e.dy == 0 then break end
      e.tc, e.tr = e.tc + e.dx, e.tr + e.dy
      tx, ty = e.tc * T, e.tr * T
    elseif G.bombs[idx(e.tc, e.tr)] and not (e.x == tx and e.y == ty) then
      -- a bomb appeared on the tile it was heading to: turn back
      e.tc, e.tr = e.tc - e.dx, e.tr - e.dy
      e.dx, e.dy = -e.dx, -e.dy
      tx, ty = e.tc * T, e.tr * T
    end
    local ddx, ddy = tx - e.x, ty - e.y
    local d = abs(ddx) + abs(ddy)
    if d <= dist then
      e.x, e.y = tx, ty
      dist = dist - d
    else
      if ddx ~= 0 then e.x = e.x + (ddx > 0 and dist or -dist) end
      if ddy ~= 0 then e.y = e.y + (ddy > 0 and dist or -dist) end
      dist = 0
    end
  end
  local fr = floor(e.anim * (e.kind == "jeet" and 8 or 4)) % 2 + 1
  if e.fr ~= fr then e.fr = fr e.img:set(IMG[e.kind .. fr]) end
  e.img:pos(MX + floor(e.x), MY + floor(e.y))
end

-- ------------------------------------------------------------------ player
local function make_player()
  local p = {x = T, y = T, dir = "d", walk = 0, alive = true, dying = 0, shield = 0, want = nil}
  p.img = ui.image(MX + p.x, MY + p.y, IMG[settings.skin .. "_d0"])
  return p
end

local function player_can(c, r)
  if not passable_tile(c, r, run.pass) then return false end
  local b = G.bombs[idx(c, r)]
  if b and not b.pass then return false end
  return true
end

local function move_axis(p, dx, dy, dist)
  local cx, cy = p.x + 8, p.y + 8
  local tc, tr = floor(cx / T), floor(cy / T)
  local ccx, ccy = tc * T + 8, tr * T + 8
  if dx ~= 0 then
    if cy ~= ccy then
      if player_can(tc + dx, tr) then
        local d = min(dist, abs(cy - ccy))
        cy = cy + (ccy > cy and d or -d)
        dist = dist - d
      else
        -- corner assist: lean into the next row if that way is open
        local nr = cy < ccy and tr - 1 or tr + 1
        if abs(cy - ccy) >= 4 and player_can(tc + dx, nr) and player_can(tc, nr) then
          local target = nr * T + 8
          local d = min(dist, abs(target - cy))
          cy = cy + (target > cy and d or -d)
        end
        p.x, p.y = cx - 8, cy - 8
        return
      end
    end
    if dist > 0 then
      local nx = cx + dx * dist
      if not player_can(tc + dx, tr) then
        if dx > 0 then nx = min(nx, ccx) else nx = max(nx, ccx) end
      end
      cx = nx
    end
  else
    if cx ~= ccx then
      if player_can(tc, tr + dy) then
        local d = min(dist, abs(cx - ccx))
        cx = cx + (ccx > cx and d or -d)
        dist = dist - d
      else
        local nc = cx < ccx and tc - 1 or tc + 1
        if abs(cx - ccx) >= 4 and player_can(nc, tr + dy) and player_can(nc, tr) then
          local target = nc * T + 8
          local d = min(dist, abs(target - cx))
          cx = cx + (target > cx and d or -d)
        end
        p.x, p.y = cx - 8, cy - 8
        return
      end
    end
    if dist > 0 then
      local ny = cy + dy * dist
      if not player_can(tc, tr + dy) then
        if dy > 0 then ny = min(ny, ccy) else ny = max(ny, ccy) end
      end
      cy = ny
    end
  end
  p.x, p.y = cx - 8, cy - 8
end

local KEYDIR = {left = {-1, 0, "l"}, right = {1, 0, "r"}, up = {0, -1, "u"}, down = {0, 1, "d"}}

local function kill_player(why)
  local p = G.player
  if not p.alive or G.cleared then return end
  p.alive = false
  p.dying = 0
  G.why = why
  flash(0xFF2040, 0.6)
end

local kick, detonate_all         -- defined with the bombs below

local function update_player(dt)
  local p = G.player
  if not p.alive then
    p.dying = p.dying + dt
    local k = p.dying
    local f = k < 0.25 and "_x1" or k < 0.6 and "_x2" or k < 0.9 and "_x3" or k < 1.2 and "_x4" or nil
    if f then f = settings.skin .. f end
    if f then p.img:set(IMG[f]) else p.img:show(false) end
    return
  end
  if p.shield > 0 then
    p.shield = max(0, p.shield - dt)
    p.img:show(p.shield > 2 or floor(p.shield * 10) % 2 == 0)
  end
  local keys = sys.keys and sys.keys() or {}
  local k = nil
  if p.tap and p.tap > 0 then p.tap = p.tap - dt end
  if p.want and (keys[p.want] or (p.tap and p.tap > 0)) then k = p.want
  else
    for _, name in ipairs({"left", "right", "up", "down"}) do
      if keys[name] then k = name break end
    end
  end
  if p.curse then
    p.curse_t = p.curse_t - dt
    if p.curse_t <= 0 then p.curse = nil end
  end
  if keys.select and run.remote then
    p.hold = (p.hold or 0) + dt
    if p.hold >= 0.5 and not p.fired then p.fired = true detonate_all() end
  else
    p.hold, p.fired = 0, false
  end
  local moving = false
  if k then
    if p.curse == "reverse" then
      k = ({left = "right", right = "left", up = "down", down = "up"})[k]
    end
    local d = KEYDIR[k]
    local speed = (46 + run.speed * 12) * (p.curse == "slow" and 0.5 or 1) * (ibrl and 1.4 or 1)
    local ox, oy = p.x, p.y
    move_axis(p, d[1], d[2], speed * dt)
    p.dir = d[3]
    moving = (p.x ~= ox or p.y ~= oy)
    if moving then p.walk = p.walk + abs(p.x - ox) + abs(p.y - oy)
    elseif run.kick then kick(d[1], d[2]) end
  end
  local fr = 0
  if moving then
    local seq = {1, 0, 2, 0}
    fr = seq[floor(p.walk / 5) % 4 + 1]
  end
  local name = settings.skin .. "_" .. p.dir .. fr
  if p.frame ~= name then p.frame = name p.img:set(IMG[name]) end
  p.img:pos(MX + floor(p.x), MY + floor(p.y))
  -- bombs the player has stepped off become solid
  for i, b in pairs(G.bombs) do
    if b.pass then
      local bx, by = (i % COLS) * T, (i // COLS) * T
      if abs(p.x - bx) >= T or abs(p.y - by) >= T then b.pass = false end
    end
  end
end

-- ------------------------------------------------------------------ bombs and flames
-- REMOTE: hold SELECT to set off every waiting bomb (not the one under you);
-- with no bomb left to place, a tap sets off the oldest one
function detonate_all()
  local pc, pr = ent_tile(G.player)
  local mine = idx(pc, pr)
  for i, b in pairs(G.bombs) do
    if b.remote and not b.lit and i ~= mine then b.lit = true b.t = 0 end
  end
end

local function detonate_oldest()
  local best
  for _, b in pairs(G.bombs) do
    if b.remote and not b.lit and (not best or b.order < best.order) then best = b end
  end
  if best then best.lit = true best.t = 0 end
end

local function place_bomb()
  local p = G.player
  if not p.alive or G.cleared or G.intro > 0 then return end
  if p.curse == "nobomb" then return end
  local c, r = ent_tile(p)
  local i = idx(c, r)
  if G.nbombs >= run.bombs or G.bombs[i] or G.grid[i] ~= FLOOR then
    if run.remote then detonate_oldest() end
    return
  end
  G.order = G.order + 1
  G.bombs[i] = {t = FUSE, range = run.fire, pass = true, remote = run.remote,
    pierce = run.pierce, order = G.order}
  G.nbombs = G.nbombs + 1
  touch(i)
end

local function foe_at(c, r)
  for _, e in ipairs(G.foes) do
    if e.alive then
      local ec, er = ent_tile(e)
      if ec == c and er == r then return true end
    end
  end
  return false
end

-- KICK: send the bomb in front of the player sliding
function kick(dx, dy)
  local p = G.player
  local c, r = ent_tile(p)
  local b = G.bombs[idx(c + dx, r + dy)]
  if b and not b.slide then b.slide = {dx, dy} b.st = 0 b.pass = false end
end

local function add_flame(i, kind)
  local f = G.flames[i]
  if f and f.kind ~= kind then
    local horiz = {h = true, el = true, er = true}
    local a, b = horiz[f.kind] or false, horiz[kind] or false
    if f.kind == "c" or kind == "c" or a ~= b then kind = "c" end
  end
  G.flames[i] = {t = FLAME_T, kind = kind, blast = f and f.blast or G.blast}
end

local function explode(i)
  local b = G.bombs[i]
  if not b then return end
  G.bombs[i] = nil
  G.nbombs = G.nbombs - 1
  G.blast = G.blast + 1
  G.blast_kills[G.blast] = 0
  add_flame(i, "c")
  flash(0x9945FF, 0.12)
  local c0, r0 = i % COLS, i // COLS
  local ends = {[1] = {"h", "er"}, [-1] = {"h", "el"}}
  local vends = {[1] = {"v", "ed"}, [-1] = {"v", "eu"}}
  for _, d in ipairs(DIRS) do
    for n = 1, b.range do
      local c, r = c0 + d[1] * n, r0 + d[2] * n
      local j = idx(c, r)
      local t = G.grid[j]
      if t == WALL or t == BAR or t == nil then break end
      if t == BLOCK then
        if not G.breaking[j] then G.breaking[j] = BREAK_T end
        if not b.pierce then break end
        -- FIREDANCER: the flame keeps going, and burns whoever hides in the fork
        add_flame(j, "c")
      elseif G.bombs[j] then
        G.bombs[j].t = min(G.bombs[j].t, 0.06)
        G.bombs[j].lit = true
        break
      else
        local it = G.items[j]
        if it and it ~= "gate" and not G.fresh[j] then
          G.items[j] = nil
          touch(j)
        elseif it == "gate" and G.gate_cool <= 0 then
          G.gate_cool = 3
          G.spawn_at_gate = 2
        end
        local pair = d[1] ~= 0 and ends[d[1]] or vends[d[2]]
        add_flame(j, n == b.range and pair[2] or pair[1])
      end
    end
  end
end

local function update_bombs(dt)
  -- kicked bombs slide a tile every 70 ms until something is in the way
  local sliding = {}
  for i, b in pairs(G.bombs) do
    if b.slide then sliding[#sliding + 1] = i end
  end
  for _, start in ipairs(sliding) do
    local i = start
    local b = G.bombs[i]
    b.st = b.st + dt
    while b.slide and b.st >= 0.07 do
      b.st = b.st - 0.07
      local c, r = i % COLS + b.slide[1], i // COLS + b.slide[2]
      local j = idx(c, r)
      local pc, pr = ent_tile(G.player)
      if passable_tile(c, r, false) and not G.bombs[j] and not foe_at(c, r)
        and not (pc == c and pr == r) and not G.items[j] then
        G.bombs[j], G.bombs[i] = b, nil
        touch(i) touch(j)
        i = j
      else
        b.slide = nil
      end
    end
  end
  local due = {}
  for i, b in pairs(G.bombs) do
    if not b.remote or b.lit then b.t = b.t - dt end
    if b.t <= 0 then due[#due + 1] = i end
  end
  for _, i in ipairs(due) do explode(i) end
  for i, f in pairs(G.flames) do
    f.t = f.t - dt
    if f.t <= 0 then G.flames[i] = nil touch(i) end
  end
  for i, t in pairs(G.breaking) do
    local nt = t - dt
    if nt <= 0 then
      G.breaking[i] = nil
      G.grid[i] = FLOOR
      run.score = run.score + 10
      if G.deco[i] then
        G.pic_left = G.pic_left - 1
        if G.pic_left == 0 then
          -- WAGMI: the whole picture is gone
          run.score = run.score + 2000
          ui.toast(find_secret("wagmi") .. "WAGMI! Picture cleared +2000")
          flash(0x14F195, 0.6)
        end
      end
      if G.items[i] then G.fresh[i] = 0.6 end
      touch(i)
    else
      G.breaking[i] = nt
    end
  end
  for i, t in pairs(G.fresh) do
    if t - dt <= 0 then G.fresh[i] = nil else G.fresh[i] = t - dt end
  end
end

-- ------------------------------------------------------------------ collisions
local function check_hits()
  local p = G.player
  local pc, pr = ent_tile(p)
  if p.alive then
    if G.flames[idx(pc, pr)] and p.shield <= 0 then kill_player("Caught in the blast") end
    for _, e in ipairs(G.foes) do
      if e.alive and abs(e.x - p.x) < 11 and abs(e.y - p.y) < 11 and p.shield <= 0 then
        kill_player(FOES[e.kind].name .. " got you")
      end
    end
  end
  for _, e in ipairs(G.foes) do
    if e.alive then
      local ec, er = ent_tile(e)
      local f = G.flames[idx(ec, er)]
      if f then
        e.alive = false
        local n = (G.blast_kills[f.blast] or 0) + 1
        G.blast_kills[f.blast] = n
        local pts = FOES[e.kind].score * (1 << (n - 1))
        run.score = run.score + pts
        popup(floor(e.x) + 8, floor(e.y), tostring(pts))
      end
    end
  end
  -- pick-ups and the gate
  if p.alive then
    local i = idx(pc, pr)
    local it = G.items[i]
    if it and it ~= "gate" and G.grid[i] == FLOOR then
      G.items[i] = nil
      touch(i)
      local text = PU_TEXT[it]
      if it == "bomb" then run.bombs = min(8, run.bombs + 1)
      elseif it == "fire" then run.fire = min(8, run.fire + 1)
      elseif it == "speed" then run.speed = min(3, run.speed + 1)
      elseif it == "shield" then p.shield = 10
      elseif it == "max" then run.fire = 8
      elseif it == "pierce" then run.pierce = true
      elseif it == "kick" then run.kick = true
      elseif it == "remote" then run.remote = true
      elseif it == "pass" then run.pass = true
      elseif it == "life" then run.lives = min(9, run.lives + 1)
      elseif it == "time" then G.time = G.time + 30
      elseif it == "curse" then
        local kinds = {"slow", "nobomb", "reverse"}
        p.curse = kinds[random(#kinds)]
        p.curse_t = 8
        text = ({slow = "OUTAGE! SLOW MODE 8s", nobomb = "OUTAGE! NO BOMBS 8s",
          reverse = "OUTAGE! CONTROLS FLIPPED 8s"})[p.curse]
      end
      ui.toast(text)
      flash(it == "curse" and 0xFF2040 or 0x14F195, 0.3)
      run.score = run.score + 50
    elseif it == "gate" and G.open and G.grid[i] == FLOOR then
      local cx, cy = p.x + 8, p.y + 8
      if abs(cx - (pc * T + 8)) < 5 and abs(cy - (pr * T + 8)) < 5 then
        G.cleared = true
        G.clear_t = 0
      end
    end
  end
end

-- ------------------------------------------------------------------ stage lifecycle
local start_stage, show_title, show_help, show_over, show_win, show_lb, show_settings
local show_secrets, secrets_label, menu_draw

local function free_stage()
  clear_popups()
  clear_overlay()
  G = nil
  hud = {}
  last_hud = {}
  ui.clear()
  leds_off()
end

local function spawn_foes(st)
  local spots = {}
  for r = 1, ROWS - 2 do
    for c = 1, COLS - 2 do
      if G.grid[idx(c, r)] == FLOOR and c + r >= 9 then spots[#spots + 1] = {c, r} end
    end
  end
  for _, kind in ipairs(st.foes) do
    if #spots == 0 then break end
    local k = random(#spots)
    local s = table.remove(spots, k)
    make_foe(kind, s[1], s[2])
  end
end

function start_stage()
  free_stage()
  local st = STAGES[run.stage]
  load_world(st.w)
  ui.bg(BG)
  G = {
    st = st, bombs = {}, flames = {}, breaking = {}, items = {}, fresh = {},
    drawn = {}, touched = {}, foes = {}, nbombs = 0, blast = 0, blast_kills = {},
    clock = 0, time = STAGE_TIME, open = false, cleared = false, gate_cool = 0,
    spawn_at_gate = 0, intro = 2.0, order = 0,
  }
  local grid, deco, blocks, logo = build_map(st)
  G.grid, G.deco = grid, deco
  G.pic_left = 0
  for k in pairs(deco) do G.pic_left = G.pic_left + 1 end
  -- the gate and the stage's own power-up under two different blocks,
  -- then a random bonus under about one fork in five (one in three in the picture)
  local a = table.remove(blocks, random(#blocks))
  local b = table.remove(blocks, random(#blocks))
  G.items[a] = "gate"
  G.items[b] = st.pu
  G.gate = a
  local total = 0
  for _, it in ipairs(ITEMS) do
    if run.stage >= it[3] then total = total + it[2] end
  end
  for _, i in ipairs(blocks) do
    if random() < (logo[i] and LOGO_ITEM_CHANCE or ITEM_CHANCE) then
      local roll = random() * total
      for _, it in ipairs(ITEMS) do
        if run.stage >= it[3] then
          roll = roll - it[2]
          if roll <= 0 then G.items[i] = it[1] break end
        end
      end
    end
  end
  canvas = ui.canvas(MX, MY, COLS * T, ROWS * T, {scale = 1, color = BG})
  for i = 0, COLS * ROWS - 1 do draw_tile(i) end
  spawn_foes(st)
  G.player = make_player()
  hud_build(st)
  hud_update()
  -- intro card
  local W = A.worlds[st.w]
  local band = ui.rect(0, 70, ui.W, 74, {color = 0x0B0A14})
  overlay[#overlay + 1] = band
  overlay[#overlay + 1] = ui.gradient(0, 70, ui.W, 3)
  overlay[#overlay + 1] = ui.gradient(0, 141, ui.W, 3)
  local label = (run.epoch > 1 and ("EPOCH " .. run.epoch .. "  ") or "") .. "STAGE " .. stage_name(run.stage, 1)
  if ibrl then center_label(54, "IBRL MODE", 14, "yellow") end
  center_label(80, label, 32, "text")
  center_label(118, W.name .. "  -  find the Finality gate", 14, W.L)
  save.stage, save.epoch = run.stage, run.epoch
  persist()
  scene = "play"
end

local function stage_cleared()
  local bonus = max(0, floor(G.time)) * 10
  run.score = run.score + bonus
  if run.score > save.best then save.best = run.score end
  local band = ui.rect(0, 70, ui.W, 74, {color = 0x0B0A14})
  overlay[#overlay + 1] = band
  overlay[#overlay + 1] = ui.gradient(0, 70, ui.W, 3)
  overlay[#overlay + 1] = ui.gradient(0, 141, ui.W, 3)
  center_label(80, "FINALIZED!", 32, "green")
  center_label(118, "time bonus " .. bonus, 14, "text")
  if G.clock - 2.0 < 60 then       -- play time, without the 2 s intro card
    -- PROOF OF HISTORY: a stage cleared in under a minute
    run.score = run.score + 1500
    center_label(52, "PROOF OF HISTORY +1500", 14, "yellow")
    local pre = find_secret("poh")
    if pre ~= "" then ui.toast(pre .. "PROOF OF HISTORY") end
  end
  award("s" .. run.stage, LAMP_STAGE, "stage " .. run.stage .. " cleared")
end

-- send the run's score to the board when it beats what this run already sent
local function submit_run(stage, epoch)
  if run and run.score > (run.sent or 0) then
    run.sent = run.score
    submit_score(run.score, stage, epoch)
  end
end

local function award_best()
  if run and run.score > run.best_at_start and run.score > 0 then
    award("best", LAMP_BEST, "new best score")
  end
end

local function next_stage()
  run.stage = run.stage + 1
  if run.stage > #STAGES then
    run.stage = 1
    run.epoch = run.epoch + 1
    if run.score > save.best then save.best = run.score end
    save.stage, save.epoch = 1, run.epoch
    persist()
    -- the epoch bonus is for playing all 8 stages, not for a CONTINUE at 4-2
    if run.from_stage == 1 then award("epoch", LAMP_EPOCH, "epoch finished") end
    award_best()
    submit_run(8, run.epoch - 1)
    show_win()
    return
  end
  start_stage()
end

local function lost_life()
  run.lives = run.lives - 1
  run.kick, run.remote, run.pierce, run.pass = false, false, false, false
  run.speed = max(0, run.speed - 1)
  if run.lives <= 0 then
    if run.score > save.best then save.best = run.score end
    persist()
    award_best()
    submit_run(run.stage, run.epoch)
    show_over()
    return
  end
  start_stage()
end

-- ------------------------------------------------------------------ the play loop
local function update_leds(dt)
  if not has_led then return end
  if led_flash > 0 then
    led_flash = led_flash - dt
    for n = 1, 6 do led_put(n, led_flash_col) end
  else
    -- top LEDs: the fuse of the bomb closest to going off
    local tmin = nil
    for _, b in pairs(G.bombs) do
      if (not b.remote or b.lit) and (not tmin or b.t < tmin) then tmin = b.t end
    end
    local lit = tmin and math.ceil(tmin / FUSE * 6) or 0
    for n = 1, 6 do
      if n <= lit then led_put(n, tmin < 0.8 and 0xFF3020 or 0xFF8A3D)
      elseif G.open then led_put(n, (floor(G.clock * 6) % 6 + 1 == n) and 0x14F195 or 0)
      else led_put(n, 0) end
    end
  end
  led_put(7, run.lives >= 1 and 0x14F195 or 0x300000)
  led_put(8, run.lives >= 2 and 0x14F195 or 0x300000)
end

local function play_tick(dt)
  G.clock = G.clock + dt
  if G.intro > 0 then
    G.intro = G.intro - dt
    if G.intro <= 0 then clear_overlay() end
    update_leds(dt)
    return
  end
  if G.cleared then
    if not G.clear_shown then G.clear_shown = true stage_cleared() end
    G.clear_t = G.clear_t + dt
    for n = 1, 8 do
      if has_led then led_put(n, (floor(G.clock * 12) % 8 + 1 == n) and 0x14F195 or 0x002010) end
    end
    if G.clear_t > 2.6 then next_stage() end
    return
  end
  if G.player.alive then
    G.time = G.time - dt
    if G.time <= 0 then kill_player("Slot missed: time out") end
  end
  update_player(dt)
  update_bombs(dt)
  for _, e in ipairs(G.foes) do update_foe(e, dt) end
  check_hits()
  -- drop the foes that finished dying
  local alive = 0
  for k = #G.foes, 1, -1 do
    local e = G.foes[k]
    if e.gone then table.remove(G.foes, k) elseif e.alive then alive = alive + 1 end
  end
  if alive == 0 and not G.open then
    G.open = true
    if G.grid[G.gate] == BLOCK then
      -- still hidden under its fork: crack the fork so the player can see where to go
      if not G.breaking[G.gate] then G.breaking[G.gate] = BREAK_T end
      ui.toast("All clear: the Finality gate breaks out of its fork")
    else
      ui.toast("All clear: the Finality gate is open")
    end
    flash(0x14F195, 0.4)
    touch(G.gate)
  end
  if G.gate_cool > 0 then G.gate_cool = G.gate_cool - dt end
  if G.spawn_at_gate > 0 and not G.flames[G.gate] then
    local c, r = G.gate % COLS, G.gate // COLS
    for _ = 1, G.spawn_at_gate do make_foe("fud", c, r) end
    G.spawn_at_gate = 0
    G.open = false
    touch(G.gate)
    ui.toast("You hit the gate: FUD spreads!")
  end
  if not G.player.alive and G.player.dying > 1.6 then
    lost_life()
    return
  end
  redraw_dirty()
  update_popups(dt)
  hud_update()
  update_leds(dt)
end

