  if title_anim.gm and title_anim.gm > 0 then
    title_anim.gm = title_anim.gm - dt
    for n = 1, 8 do led_put(n, (floor(t * 20) + n) % 2 == 0 and 0xFFFFFF or 0x14F195) end
    return
  end
  if has_led then
    for n = 1, 6 do
      local ph = (floor(t * 8) + n) % 6
      led_put(n, ph < 2 and 0x9945FF or ph < 4 and 0x3FD8E8 or 0x14F195)
    end
    led_put(7, 0) led_put(8, 0)
  end
end

local function new_run(stage, epoch)
  run = {stage = stage, epoch = epoch, score = 0, lives = 3, bombs = 1, fire = 1, speed = 0,
    best_at_start = save.best, from_stage = stage}
  if stage > 1 or epoch > 1 then
    -- a continue starts with a little firepower for where it lands
    run.bombs = min(4, 1 + floor((stage - 1) / 2))
    run.fire = min(4, 1 + floor((stage - 1) / 2))
  end
  start_stage()
end

