  if has_led then for n = 1, 8 do led_put(n, 0x500A0A) end end
end

function show_win()
  scene = "win"
  end_card("FINALITY!", "green", "score " .. run.score, "epoch " .. run.epoch .. " begins: foes are faster")
  ui.hint("SELECT next stage   UP share on X")
  if has_led then for n = 1, 8 do led_put(n, 0x14F195) end end
end

-- ------------------------------------------------------------------ host callbacks
-- secret codes typed on the title screen (directions only)
local CODES = {
  ibrl = "up up down down left right left right",
  skin = "left right left right up up",
  gm = "up down up down left right",
}
local typed = {}
local function check_codes(key)
  typed[#typed + 1] = key
  if #typed > 8 then table.remove(typed, 1) end
  local s = table.concat(typed, " ")
  for name, code in pairs(CODES) do
    if s:sub(-#code) == code then
      typed = {}
      local pre = find_secret(name)
      if name == "ibrl" then
        ibrl = not ibrl
        local on = pre ~= "" and "IBRL MODE ON" or "IBRL MODE ON: increase bandwidth, reduce latency"
        ui.toast(pre .. (ibrl and on or "IBRL MODE OFF"))
      elseif name == "skin" then
        local order = {"hero", "toly", "mert"}
        if all_secrets() then order[#order + 1] = "gold" end
        local n = 0
        for k, v in ipairs(order) do if v == settings.skin then n = k end end
        -- a fresh find of the 5th secret already put on GOLD VAL: keep it on
        if pre == "" or settings.skin ~= "gold" then settings.skin = order[n % #order + 1] end
        save_settings()
        local note = settings.skin == "gold" and " (all secrets)" or settings.skin ~= "hero" and " (tribute skin)" or ""
        ui.toast(pre .. "Hero: " .. SKINS[settings.skin] .. note)
      else
        ui.toast(pre .. "gm gm. WAGMI")
        title_anim.gm = 1.2
      end
      title_anim.hero:set(IMG[settings.skin .. "_r0"])
      if pre ~= "" then secrets_label() end
      return
    end
  end
end

function on_key(key, rep)
  if scene == "title" then
    if key == "back" then return false end
    if KEYDIR[key] and not rep then check_codes(key) end
    if key == "up" then menu_sel = (menu_sel - 2) % #menu + 1 menu_draw()
    elseif key == "down" then menu_sel = menu_sel % #menu + 1 menu_draw()
    elseif key == "select" then
      local id = menu[menu_sel].id
      if id == "new" then new_run(1, 1)
      elseif id == "cont" then new_run(save.stage, save.epoch)
      elseif id == "lb" then show_lb()
      elseif id == "settings" then show_settings()
      elseif id == "secrets" then show_secrets()
      else help_page = 1 show_help() end
    end
    return true
  elseif scene == "help" then
    if key == "back" then show_title()
    elseif key == "right" or key == "select" then help_page = help_page % HELP_PAGES + 1 show_help()
    elseif key == "left" then help_page = (help_page - 2) % HELP_PAGES + 1 show_help() end
    return true
  elseif scene == "lb" then
    if key == "back" then show_title() elseif key == "select" then lb_fetch()
    elseif key == "up" then show_share(save.best, nil, show_lb) end
    return true
  elseif scene == "share" then
    if key == "back" or key == "select" then (share_back or show_title)() end
    return true
  elseif scene == "secrets" then
    if key == "back" or key == "select" then show_title() end
    return true
  elseif scene == "author" then
    if key == "back" or key == "select" then show_settings() end
    return true
  elseif scene == "settings" then
    if key == "back" then show_title()
    elseif key == "up" then set_sel = (set_sel - 2) % #set_rows + 1 settings_draw()
    elseif key == "down" then set_sel = set_sel % #set_rows + 1 settings_draw()
    elseif key == "select" then settings_select() end
    return true
  elseif scene == "over" then
    if key == "up" then show_share(run.score, run.epoch .. "-" .. run.stage, show_over)
    elseif key == "select" or key == "back" then show_title() end
    return true
  elseif scene == "win" then
    if key == "up" then show_share(run.score, run.epoch .. "-" .. run.stage, show_win)
    elseif key == "select" then start_stage() elseif key == "back" then show_title() end
    return true
  elseif scene == "play" then
    if paused then
      if key == "select" then set_pause(false)
      elseif key == "back" and not rep then
        if run.score > save.best then save.best = run.score end
        persist()
        award_best()
        submit_run(run.stage, run.epoch)
        show_title()
      end
      return true
    end
    if key == "back" then
      if not rep and G and G.intro <= 0 and not G.cleared then set_pause(true) end
      return true
    end
    if key == "select" then place_bomb() return true end
    if KEYDIR[key] and G then
      -- a quick tap still moves a little, even if no tick sees the key held
      G.player.want = key
      G.player.tap = 0.14
    end
    return true
  end
  return true
end

function on_tick(ms)
  local dt = min(ms, 60) / 1000
  if scene == "play" and G and not paused then
    play_tick(dt)
  elseif scene == "title" then
    title_tick(dt)
  end
end

function on_exit()
  if run and run.score > save.best then save.best = run.score end
  persist()
  leds_off()
end

show_title()
